struct AlertBuffer {
public:
    AlertBuffer * _next;
    int _sent;
    int _count;
    char _buffer[8];
};
static_assert(sizeof(AlertBuffer) == 0x18, "sizeof AlertBuffer");
static_assert(offsetof(AlertBuffer, _next) == 0x0, "AlertBuffer::_next");
static_assert(offsetof(AlertBuffer, _sent) == 0x8, "AlertBuffer::_sent");
static_assert(offsetof(AlertBuffer, _count) == 0xC, "AlertBuffer::_count");
static_assert(offsetof(AlertBuffer, _buffer) == 0x10, "AlertBuffer::_buffer");

struct AlertBufferList {
public:
    AlertBuffer * _head;
    AlertBuffer * _tail;
    int _count;
};
static_assert(sizeof(AlertBufferList) == 0x18, "sizeof AlertBufferList");
static_assert(offsetof(AlertBufferList, _head) == 0x0, "AlertBufferList::_head");
static_assert(offsetof(AlertBufferList, _tail) == 0x8, "AlertBufferList::_tail");
static_assert(offsetof(AlertBufferList, _count) == 0x10, "AlertBufferList::_count");

class Thread {
public:
    virtual ~Thread();  // slot 0
    virtual void yield();  // slot 1
    virtual wchar_t const * Name() = 0;  // slot 2
    virtual void run() = 0;  // slot 3
    virtual void stop();  // slot 4
    unsigned long long _id;
    long long _lastExecuted;
    long long _maxFrozenSeconds;
    ThreadManager * _threadManager;
    bool _run;
};
static_assert(sizeof(Thread) == 0x30, "sizeof Thread");
static_assert(offsetof(Thread, _id) == 0x8, "Thread::_id");
static_assert(offsetof(Thread, _lastExecuted) == 0x10, "Thread::_lastExecuted");
static_assert(offsetof(Thread, _maxFrozenSeconds) == 0x18, "Thread::_maxFrozenSeconds");
static_assert(offsetof(Thread, _threadManager) == 0x20, "Thread::_threadManager");
static_assert(offsetof(Thread, _run) == 0x28, "Thread::_run");

class AlertSender : public Thread {
public:
    virtual wchar_t const * Name();
    virtual ~AlertSender();
    virtual void run();
    unsigned long long _socket;
    void * _sockEvent;
    void * _itemEvent;
    unsigned long long _threadId;
    int _maxLogCount;
    bool _init;
    alignas(2) unsigned char _remoteAddr[0x10];  // ❓ PDB type 0x2227: sockaddr
    short _daemonNameBytes;
    wchar_t _daemonName[64];
    short _versionBytes;
    wchar_t _version[64];
    int _worldId;
    alignas(8) unsigned char _cs[0x28];  // ❓ PDB type 0x1052: _RTL_CRITICAL_SECTION
    AlertBufferList _bufferList;
};
static_assert(sizeof(AlertSender) == 0x1B0, "sizeof AlertSender");
static_assert(offsetof(AlertSender, _socket) == 0x30, "AlertSender::_socket");
static_assert(offsetof(AlertSender, _sockEvent) == 0x38, "AlertSender::_sockEvent");
static_assert(offsetof(AlertSender, _itemEvent) == 0x40, "AlertSender::_itemEvent");
static_assert(offsetof(AlertSender, _threadId) == 0x48, "AlertSender::_threadId");
static_assert(offsetof(AlertSender, _maxLogCount) == 0x50, "AlertSender::_maxLogCount");
static_assert(offsetof(AlertSender, _init) == 0x54, "AlertSender::_init");
static_assert(offsetof(AlertSender, _remoteAddr) == 0x56, "AlertSender::_remoteAddr");
static_assert(offsetof(AlertSender, _daemonNameBytes) == 0x66, "AlertSender::_daemonNameBytes");
static_assert(offsetof(AlertSender, _daemonName) == 0x68, "AlertSender::_daemonName");
static_assert(offsetof(AlertSender, _versionBytes) == 0xE8, "AlertSender::_versionBytes");
static_assert(offsetof(AlertSender, _version) == 0xEA, "AlertSender::_version");
static_assert(offsetof(AlertSender, _worldId) == 0x16C, "AlertSender::_worldId");
static_assert(offsetof(AlertSender, _cs) == 0x170, "AlertSender::_cs");
static_assert(offsetof(AlertSender, _bufferList) == 0x198, "AlertSender::_bufferList");

